;sliders[key]=slider;slider.ValueChanged+=(s,e)=>{if(updating)return;typeof(RobotStyleParameters).GetProperty(key).SetValue(settings.Style,slider.Value/100.0,null);QueuePreview();};stylePanel.Controls.Add(label);stylePanel.Controls.Add(slider);}var hidden=new CheckBox{Text="Предпочитать скрытый крепёж",Width=280,Checked=settings.Style.HiddenFasteners};hidden.CheckedChanged+=(s,e)=>{if(updating)return;settings.Style.HiddenFasteners=hidden.Checked;QueuePreview();};if(settings.Connected){updating=true;hidden.Checked=false;updating=false;hidden.Enabled=false;hidden.Text="Крепёж доступен для обслуживания";}stylePanel.Controls.Add(hidden);autoPreview.Text="Перестраивать после изменения";autoPreview.Checked=true;autoPreview.Width=280;stylePanel.Controls.Add(autoPreview);mechanical.Dock=DockStyle.Fill;mechanical.ToolbarVisible=false;mechanical.SelectedObject=SettingsView();mechanical.PropertyValueChanged+=(s,e)=>{foreach(var pair in sliders)pair.Value.Enabled=!settings.Connected||pair.Key=="AccentColorCoverage"||!settings.BlenderDesign&&(pair.Key=="Slimness"||pair.Key=="AccentColorCoverage"||pair.Key=="Roundness"&&(settings.ReferenceDesign||settings.Style.Profile!="oval")||pair.Key=="Smoothness"&&!settings.ReferenceDesign);QueuePreview();};mechanicTab.Controls.Add(mechanical);var componentsPanel=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=100,Padding=new Padding(5)};componentsPanel.Controls.Add(componentPicker);Add(componentsPanel,"Убрать из компоновки",()=>{var c=componentPicker.SelectedItem as BodyPhysicalComponent;if(c==null||busy)return;settings.Components.RemoveAll(x=>x.Id==c.Id);RefreshComponents();QueuePreview();});mechanicTab.Controls.Add(componentsPanel);RefreshComponents();variants.Dock=DockStyle.Fill;variants.SelectedIndexChanged+=(s,e)=>{var name=variants.SelectedItem as string;if(name!=null&&choices.ContainsKey(name)){settings=configs.ContainsKey(name)?Clone(configs[name]):settings;updating=true;foreach(var pair in sliders)pair.Value.Value=(int)Math.Round((double)typeof(RobotStyleParameters).GetProperty(pair.Key).GetValue(settings.Style,null)*100);if(settings.Connected)foreach(var pair in sliders)pair.Value.Enabled=pair.Key=="AccentColorCoverage"||!settings.BlenderDesign&&(pair.Key=="Slimness"||pair.Key=="AccentColorCoverage"||pair.Key=="Roundness"&&(settings.ReferenceDesign||settings.Style.Profile!="oval")||pair.Key=="Smoothness"&&!settings.ReferenceDesign);updating=false;mechanical.SelectedObject=SettingsView();RefreshComponents();Show(choices[name]);}};variantTab.Controls.Add(variants);var right=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,Size=new Size(1160,850),SplitterDistance=560,Panel1MinSize=250,Panel2MinSize=170};split.Panel2.Controls.Add(right);right.Panel1.Controls.Add(viewport);fallbackHost.Child=fallback.Root;right.Panel1.Controls.Add(fallbackHost);checks.Dock=DockStyle.Fill;checks.ReadOnly=true;checks.AllowUserToAddRows=false;checks.RowHeadersVisible=false;checks.SelectionMode=DataGridViewSelectionMode.FullRowSelect;checks.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;checks.Columns.Add("status","Проверка");checks.Columns.Add("scope","Область");checks.Columns.Add("message","Результат и ограничения");checks.Columns[0].FillWeight=40;checks.Columns[1].FillWeight=55;checks.Columns[2].FillWeight=260;checks.SelectionChanged+=(s,e)=>{if(current==null||checks.CurrentRow==null)return;int index=checks.CurrentRow.Index;if(index<current.Result.Issues.Count){var issue=current.Result.Issues[index];selectedPart=issue.PartId;viewport.Select(selectedPart);}};right.Panel2.Controls.Add(checks);metrics.Dock=DockStyle.Top;metrics.Height=43;metrics.Padding=new Padding(9);right.Panel2.Controls.Add(metrics);status.Dock=DockStyle.Bottom;status.Height=55;status.Padding=new Padding(10);status.Text="Сначала каркас и посадки, затем внешняя оболочка. Проверки прочности и полного диапазона не подменяются красивым видом.";Controls.Add(split);Controls.Add(top);Controls.Add(status);kernel.Progress+=text=>{if(!disposed&&IsHandleCreated)BeginInvoke(new Action(()=>status.Text=text));};viewport.ReadyChanged+=()=>{fallbackHost.Visible=!viewport.Ready;viewport.Visible=viewport.Ready;if(fallbackHost.Visible)fallbackHost.BringToFront();if(current!=null)Render();};viewport.Message+=data=>{if(Convert.ToString(data["type"])=="select"){string id=Convert.ToString(data["id"]);selectedPart=current!=null&&current.Result.Parts.Any(p=>p.Id==id)?id:null;}else if(Convert.ToString(data["type"])=="partMoved"){MovePart(Convert.ToString(data["id"]),RobotWebViewport.Numbers(data["delta"],3));}};previewDelay.Interval=600;previewDelay.Tick+=(s,e)=>{previewDelay.Stop();Generate();};Shown+=(s,e)=>{if(current==null||current.Fingerprint!=ProceduralBodySpec.Fingerprint(snapshot,snapshot.Find(jointId),settings))Generate();else Show(current);};FormClosing+=(s,e)=>{if(busy){UiMessage.Show(this,"Дождитесь построения или отмените его.");e.Cancel=true;}};if(settings.Variant=="Reference67"){stylePanel.Controls.Clear();stylePanel.Controls.Add(new Label{Text="Компоновка по твоему дизайну. Размеры звеньев, моторов и подшипников меняются в параметрах шарниров. Здесь доступны стенки, зазор и плотность. Передача кисти и подготовка к печати ещё не завершены.",Width=280,Height=180});stylePanel.Controls.Add(autoPreview);generateVariants.Visible=false;tabs.TabPages.Remove(variantTab);}}

  static ProceduralBodySettings Clone(ProceduralBodySettings s){return CADDocument.Serializer().Deserialize<ProceduralBodySettings>(CADDocument.Serializer().Serialize(s));}

  static void Add(Control panel,string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=34};b.Click+=(s,e)=>action();panel.Controls.Add(b);}

  void QueuePreview(){if(updating)return;revision++;pending=true;insert.Enabled=false;if(autoPreview.Checked){previewDelay.Stop();previewDelay.Start();}}

  object SettingsView(){return settings.Variant=="Reference67"?(object)new Reference67Settings(settings):settings;}
  async void Generate(){if(disposed)return;if(busy){pending=true;return;}busy=true;pending=false;generate.Enabled=generateVariants.Enabled=insert.Enabled=false;int ticket=revision;var config=Clone(settings);try{config.Validate();var j=snapshot.Find(jointId);var spec=ProceduralBodySpec.Build(snapshot,j,config);if(overrides.Count>0)spec["Overrides"]=new Dictionary<string,string>(overrides);var result=await Task.Factory.StartNew(()=>kernel.Run(new CADDocument(),"body_generate",null,null,null,new Dictionary<string,object>{{"Spec",spec}}));var generated=CaptureResult(result,spec,config);if(disposed)return;if(ticket!=revision){pending=true;return;}settings=config;mechanical.SelectedObject=SettingsView();RefreshComponents();choices[config.Variant]=generated;configs[config.Variant]=Clone(config);Show(generated);}catch(Exception ex){if(!disposed){status.Text=ex.GetBaseException().Message;UiMessage.Show(this,status.Text,"Корпус не применён");}}finally{busy=false;if(!disposed){generate.Enabled=generateVariants.Enabled=true;insert.Enabled=current!=null&&current.Result.GeometryValid&&!pending;if(pending&&autoPreview.Checked){previewDelay.Stop();previewDelay.Start();}}}}

  RobotGeneratedBody CaptureResult(CADKernelResult result,Dictionary<string,object> spec,ProceduralBodySettings config){if(result.Procedural==null)throw new Exception("Нет результата процедурного ядра.");foreach(var part in result.Procedural.Parts){var body=result.Bodies.Single(x=>x.Id==part.Id);body.ReadMesh();part.Step=Convert.ToBase64String(File.ReadAllBytes(part.StepPath));part.Preview=CADMeshCodec.Encode(body.Display);part.Volume=body.Volume;part.Center=body.Center;part.Bounds=body.Bounds;part.StepPath=null;}return new RobotGeneratedBody{Fingerprint=ProceduralBodySpec.Fingerprint(snapshot,snapshot.Find(jointId),config),SpecJson=CADDocument.Serializer().Serialize(spec),Result=result.Procedural,GeneratedUtc=DateTime.UtcNow};}

  async void GenerateVariants(){if(busy||settings.Variant=="Reference67")return;previewDelay.Stop();pending=false;busy=true;stylePanel.Enabled=mechanical.Enabled=variants.Enabled=false;generate.Enabled=generateVariants.Enabled=insert.Enabled=false;variants.Items.Clear();try{foreach(string name in new[]{"Reference","Ultra Slim","Lightweight","High Strength","Easy Print"}){status.Text="Вариант "+name;var config=Clone(settings);config.Variant=name;config.Style=RobotStyleParameters.Preset(name);var spec=ProceduralBodySpec.Build(snapshot,snapshot.Find(jointId),config);var result=await Task.Factory.StartNew(()=>kernel.Run(new CADDocument(),"body_generate",null,null,null,new Dictionary<string,object>{{"Spec",spec}}));if(disposed)return;choices[name]=CaptureResult(result,spec,config);configs[name]=Clone(config);variants.Items.Add(name);}variants.SelectedIndex=0;status.Text="Пять параметрических вариантов готовы. Сравните массу и проверки; это не доказательство глобального оптимума.";}catch(Exception ex){UiMessage.Show(this,ex.GetBaseException().Message);}finally{busy=false;if(!disposed){stylePanel.Enabled=mechanical.Enabled=variants.Enabled=true;generate.Enabled=generateVariants.Enabled=true;insert.Enabled=current!=null&&current.Result.GeometryValid;}}}

  void Show(RobotGeneratedBody body){current=body;Text="Процедурный корпус · "+snapshot.Find(jointId).Name+" · "+settings.Variant;checks.Rows.Clear();foreach(var issue in body.Result.Issues){int row=checks.Rows.Add(issue.Status=="pass"?"Проверено":issue.Status=="error"?"Ошибка":issue.Status=="pending"?"Не подтверждено":"Ограничение",issue.Scope,issue.Message);checks.Rows[row].DefaultCellStyle.ForeColor=issue.Status=="error"?Color.Firebrick:issue.Status=="pass"?Color.DarkGreen:Color.DarkGoldenrod;}metrics.Text=body.Result.Parts.Count+" деталей · "+Engine.F(body.Result.MassKg)+" кг · сегментов каркаса "+body.Result.Segments+" · изменены: "+string.Join(", ",body.Result.ChangedModules);status.Text=body.Result.GeometryValid?"CAD-геометрия проверена. Допуск к изготовлению не подтверждён: прочность, крепёж и движения требуют отдельных проверок.":"Есть геометрические ошибки. Исправьте выделенные места до применения.";insert.Enabled=body.Result.GeometryValid;Render();}

  void Render(){if(current==null)return;if(fallbackHost.Visible){var assembly=new CadAssembly();foreach(var part in current.Result.Parts)assembly.Parts.Add(ProceduralBodySpec.Part(part.Id,part));fallback.SetResult(new Result{P=new Parameters{Kind=9},Model=assembly},true);fallback.Fit();return;}viewport.Clear();foreach(var part in current.Result.Parts){var model=ProceduralBodySpec.Part(part.Id,part);viewport.Part(part.Id,part.Label,model.MeshOverride,Matrix3D.Identity,ColorTranslator.FromHtml(part.Color),true,part.Role);}foreach(var c in settings.Components??new List<BodyPhysicalComponent>())if(c.Preview!=null)viewport.Part(c.Id,c.Label,CADMeshCodec.Decode(c.Preview),Matrix3D.Identity,Color.SlateGray,true,"component");foreach(var volume in current.Result.ProtectedVolumes)viewport.Send(new{type="volume",kind=volume.Kind,bounds=volume.Bounds,matrix=RobotWebViewport.Matrix(Matrix3D.Identity)});viewport.Send(new{type="issues",issues=current.Result.Issues.Select(i=>new{status=i.Status,position=i.Position,partId=i.PartId,message=i.Message}).ToArray()});if(fitPreview){viewport.Fit();fitPreview=false;}viewport.Select(selectedPart);}

  void RefreshComponents(){componentPicker.Items.Clear();foreach(var c in settings.Components??new List<BodyPhysicalComponent>())componentPicker.Items.Add(c);if(componentPicker.Items.Count>0)componentPicker.SelectedIndex=0;}

  void EditComponent(){var component=componentPicker.SelectedItem as BodyPhysicalComponent;if(component==null||busy)return;string id=component.Id;WorkspaceHost.Open(this,new CADStudioForm(CADDocument.ImportStep(Convert.FromBase64String(component.Step),component.Label),native=>{var live=settings.Components.FirstOrDefault(c=>c.Id==id);if(live==null)return false;live.Step=native.Step;live.Preview=native.Preview;QueuePreview();return true;}));}

  void Apply(){if(busy||current==null||!current.Result.GeometryValid)return;if(apply!=null&&apply(Clone(settings),current))Close();}

  void EditPart(){if(busy||current==null)return;var part=current.Result.Parts.FirstOrDefault(p=>p.Id==selectedPart);if(part==null){UiMessage.Show(this,"Выберите деталь в сцене или строку проверки.");return;}var doc=CADDocument.ImportStep(Convert.FromBase64String(part.Step),part.Label);WorkspaceHost.Open(this,new CADStudioForm(doc,native=>{part.Step=native.Step;part.Preview=native.Preview;part.Volume=native.Volume;part.Center=native.Center;overrides[part.Id]=native.Step;current.Result.GeometryValid=false;insert.Enabled=false;current.Result.Issues.Add(new BodyGenerationIssue{Code="manual_edit",Status="pending",Scope="structural",PartId=part.Id,Position=part.Center,Message="Ручная CAD-правка: перестройте проверки. Номинальное сечение каркаса не подтверждает изменённую геометрию."});Show(current);return true;}));}

  async void ImportComponent(){if(busy)return;using(var dialog=new OpenFileDialog{Filter="Компонент STEP|*.step;*.stp"})if(dialog.ShowLocalizedDialog(this)==DialogResult.OK){busy=true;try{var name=Path.GetFileNameWithoutExtension(dialog.FileName);var doc=CADDocument.ImportStep(File.ReadAllBytes(dialog.FileName),name);var result=await Task.Factory.StartNew(()=>kernel.Run(doc,"native"));if(disposed)return;var body=result.Bodies[0];body.ReadMesh();settings.Components.Add(new BodyPhysicalComponent{Id=Guid.NewGuid().ToString("N"),Label=name,Step=result.Step,Fidelity="imported",Preview=CADMeshCodec.Encode(body.Display)});RefreshComponents();QueuePreview();status.Text="STEP-компонент добавлен. Задайте его положение и перестройте корпус.";}catch(Exception ex){UiMessage.Show(this,ex.GetBaseException().Message);}finally{busy=false;}}}

  async void MovePart(string id,double[] delta){if(busy||current==null){Render();return;}var part=current.Result.Parts.FirstOrDefault(p=>p.Id==id);if(part==null){var c=settings.Components.FirstOrDefault(x=>x.Id==id);if(c!=null)MoveComponent(c,delta);return;}busy=true;try{var doc=CADDocument.ImportStep(Convert.FromBase64String(part.Step),part.Label);CADNativeBridge.AppendMove(doc,RobotMath.Translation(delta[0],delta[1],delta[2]));var result=await Task.Factory.StartNew(()=>kernel.Run(doc,"native"));if(disposed)return;var body=result.Bodies[0];body.ReadMesh();part.Step=result.Step;part.Preview=CADMeshCodec.Encode(body.Display);part.Volume=body.Volume;part.Center=body.Center;part.Bounds=body.Bounds;overrides[id]=result.Step;current.Result.GeometryValid=false;insert.Enabled=false;revision++;pending=true;Render();status.Text="Деталь перемещена в CAD. Выполняется повторная проверка зазоров.";}catch(Exception ex){if(!disposed){status.Text=ex.GetBaseException().Message;Render();}}finally{busy=false;if(!disposed&&autoPreview.Checked){previewDelay.Stop();previewDelay.Start();}}}

  async void MoveComponent(BodyPhysicalComponent component,double[] delta){if(busy)return;busy=true;try{var doc=CADDocument.ImportStep(Convert.FromBase64String(component.Step),component.Label);CADNativeBridge.AppendMove(doc,RobotMath.Translation(delta[0],delta[1],delta[2]));var result=await Task.Factory.StartNew(()=>kernel.Run(doc,"native"));if(disposed)return;result.Bodies[0].ReadMesh();component.Step=result.Step;component.Preview=CADMeshCodec.Encode(result.Bodies[0].Display);QueuePreview();Render();}catch(Exception ex){if(!disposed){status.Text=ex.GetBaseException().Message;Render();}}finally{busy=false;}}

  void Export(){if(current==null||busy)return;using(var dialog=new SaveFileDialog{Filter="STEP · отдельные CAD-тела|*.step",FileName="Процедурный_корпус.step"})if(dialog.ShowLocalizedDialog(this)==DialogResult.OK)try{var assembly=new CadAssembly();foreach(var p in current.Result.Parts)assembly.Parts.Add(ProceduralBodySpec.Part(p.Id,p));StepExport.Write(assembly,dialog.FileName);status.Text="STEP сохранён: "+dialog.FileName;}catch(Exception ex){UiMessage.Show(this,ex.Message);}}

  void SaveReport(){if(current==null)return;using(var dialog=new SaveFileDialog{Filter="JSON · параметры и проверки|*.json",FileName="Проверки_корпуса.json"})if(dialog.ShowLocalizedDialog(this)==DialogResult.OK)File.WriteAllText(dialog.FileName,CADDocument.Serializer().Serialize(current),Encoding.UTF8);}

  public bool WorkspaceCanClose(){if(!busy)return true;UiMessage.Show(this,"Дождитесь построения или отмените расчёт.");return false;}public void WorkspaceApproveClose(){}public void WorkspaceActivate(bool active){}

  protected override void Dispose(bool disposing){if(disposing&&!disposed){disposed=true;revision++;previewDelay.Dispose();kernel.Dispose();viewport.Dispose();fallback.Dispose();fallbackHost.Child=null;}base.Dispose(disposing);}

 }

}

